(()=>{"use strict";class s{constructor(s,t){this.nome=s,this.hp=t}resumo(){return`${this.nome} - Dado de Vida: d${this.hp}`}}class t{static async buscarClasses(){const s=await fetch("https://www.dnd5eapi.co/api/classes");return(await s.json()).results}static async buscarDetalhesClasse(s){const t=await fetch(`https://www.dnd5eapi.co/api/classes/${s}`);return await t.json()}}class a{static async mostrarClasses(){const a=document.getElementById("lista-classes");a.innerHTML="Carregando...";const e=await t.buscarClasses();a.innerHTML="";for(const n of e){const e=await t.buscarDetalhesClasse(n.index),c=new s(e.name,e.hit_die),i=document.createElement("div");i.classList.add("classe-item"),i.innerText=c.resumo(),a.appendChild(i)}}}document.addEventListener("DOMContentLoaded",(()=>{a.mostrarClasses()}))})();